import { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

function Dashboard() {
  const { user } = useContext(AuthContext);
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const res = await axios.get('http://localhost:5001/api/resume/my', { withCredentials: true });
        setResumes(res.data.data);
      } catch (err) {
        console.error(err);
      }
    }
    if (user) load();
  }, [user]);

  if (!user) return <div style={{ padding: 20 }}>Please login to view your dashboard</div>;

  const isRecruiter = user.role === 'recruiter' || user.role === 'admin';

  return (
    <div className="page container">
      <div className="flex justify-between items-center mb-6">
        <h1>{isRecruiter ? 'Recruiter Console' : 'Candidate Dashboard'}</h1>
        <div className="flex gap-4">
          {!isRecruiter && <a href="/upload" className="btn btn-primary">Analyze New Resume</a>}
          {isRecruiter && <a href="/create-job" className="btn btn-primary">Post New Job</a>}
        </div>
      </div>
      <p className="muted mb-10">Welcome back, {user.name || user.email}</p>

      {resumes.length === 0 ? (
        <div className="card text-center py-12">
          <p className="muted mb-6">No resumes uploaded yet.</p>
          <a href="/upload" className="btn btn-primary">Upload Now</a>
        </div>
      ) : (
        <div className="grid">
          {resumes.map(r => (
            <div key={r._id} className="card">
              <div className="flex justify-between items-center mb-4">
                <h3 className="card-title">{r.jobId?.title || 'General Analysis'}</h3>
                <div className={`score-badge ${r.score >= 75 ? 'score-good' : r.score >= 50 ? 'score-warn' : 'score-bad'}`}>
                  {Math.round(r.score || 0)}%
                </div>
              </div>

              <div className="mb-4">
                <p className="form-label">Top Skills:</p>
                <div className="flex-wrap">
                  {(r.matchedSkills || r.skills || []).slice(0, 4).map((s, i) => (
                    <span key={i} className="chip">{s}</span>
                  ))}
                </div>
              </div>

              <div className="flex justify-between items-center pt-4 border-t">
                <span className="muted small">{new Date(r.createdAt).toLocaleDateString()}</span>
                <span className={`badge ${r.interviewStatus === 'Shortlisted' ? 'bg-success' : 'bg-secondary'}`}>
                  {r.interviewStatus}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Dashboard;
